import{_ as s,o as i,c as a,a2 as t}from"./chunks/framework.BZAK_utg.js";const u=JSON.parse('{"title":"GnomeBoxes虚拟机安装与配置","description":"","frontmatter":{"title":"GnomeBoxes虚拟机安装与配置","date":"2026-07-09","categories":["安装配置","应用软件"],"tags":["Linux"],"prevTitle":"Distrobox快速上手","prevLink":"./Distrobox快速上手.html","nextTitle":"命令备忘录：IDEA","nextLink":"./命令备忘录：IDEA.html"},"headers":[],"relativePath":"posts/安装配置/GnomeBoxes虚拟机安装与配置.md","filePath":"posts/安装配置/GnomeBoxes虚拟机安装与配置.md"}'),l={name:"posts/安装配置/GnomeBoxes虚拟机安装与配置.md"};function o(n,e,p,r,d,c){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="gnomeboxes虚拟机安装与配置" tabindex="-1">GnomeBoxes虚拟机安装与配置 <a class="header-anchor" href="#gnomeboxes虚拟机安装与配置" aria-label="Permalink to &quot;GnomeBoxes虚拟机安装与配置&quot;">​</a></h1><p><code>Gnome Boxes</code>是基于<code>QEMU/KVM</code>和<code>libvirt</code>的虚拟机管理工具，其它虚拟机管理工具还有：VirtualBox、VMware等。</p><blockquote><p>VirtualBox偶尔会出现一些小毛病，比如说：VirtualBox之前出现过因为网卡bug导致虚拟机无法上网的问题，虽然当时降级安装临时解决了问题，但也折腾了一小会儿。另外，最近遇到了一个更严重的问题，启动VirtualBox时直接蓝屏报错“KERNEL PANIC！”导致系统宕机，降级也没用。不想继续折腾了，计划基于GnomeBoxes重新配置虚拟机环境。</p></blockquote><blockquote><p>操作环境：宿主机为ArchLiniux、客户机为Windows7_x86</p></blockquote><h2 id="一、安装" tabindex="-1">一、安装 <a class="header-anchor" href="#一、安装" aria-label="Permalink to &quot;一、安装&quot;">​</a></h2><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gnome-boxes</span></span></code></pre></div><p>准备后续安装包：</p><ul><li>操作系统镜像：<a href="https://msdn.itellyou.cn/" target="_blank" rel="noreferrer">cn_windows_7_ultimate_with_sp1_x86_dvd_u_677486.iso</a></li><li>虚拟机通用驱动（粘贴板共享和自适应分辨率）：<a href="https://www.spice-space.org/download/windows/spice-guest-tools/spice-guest-tools-latest.exe" target="_blank" rel="noreferrer">spice-guest-tools</a></li><li>虚拟机额外驱动（文件共享）：<a href="https://www.spice-space.org/download/windows/spice-webdavd/spice-webdavd-x86-latest.msi" target="_blank" rel="noreferrer">spice-webdavd</a></li><li>浏览器：<a href="https://download.mozilla.org/?product=firefox-esr115-latest-ssl&amp;os=win&amp;lang=zh-CN" target="_blank" rel="noreferrer">Firefox_Setup_115.37.0esr.exe</a></li></ul><h2 id="二、创建虚拟机" tabindex="-1">二、创建虚拟机 <a class="header-anchor" href="#二、创建虚拟机" aria-label="Permalink to &quot;二、创建虚拟机&quot;">​</a></h2><p>按照下述步骤创建虚拟机：</p><ul><li>打开Boxes软件</li><li>点击【+】按钮</li><li>选择【从文件中安装】</li><li>选择一个ISO文件（如前面准备的<code>cn_windows_7_ultimate_with_sp1_x86_dvd_u_677486.iso</code>）</li><li>进入创建虚拟机界面，按需调整【内存】和【存储限制】等参数（也可以后面调整）</li><li>点击【创建】</li><li>执行后续系统安装流程</li></ul><h2 id="三、配置粘贴板共享和自适应分辨率" tabindex="-1">三、配置粘贴板共享和自适应分辨率 <a class="header-anchor" href="#三、配置粘贴板共享和自适应分辨率" aria-label="Permalink to &quot;三、配置粘贴板共享和自适应分辨率&quot;">​</a></h2><p>粘贴板共享和自适应分辨率可以通过<code>spice-guest-tools</code>驱动实现（类似于<code>VirtualBox</code>中的<code>VirtualBox Guest Additions</code>）。步骤如下：</p><ul><li>在虚拟机中下载和安装<code>spice-guest-tools</code></li></ul><blockquote><p>关于下载<code>spice-guest-tools</code>的补充说明：此时物理机和虚拟机的粘贴板还没有打通，在虚拟机中直接输入官方下载链接可能不方便，另外，即使手工在虚拟机中输入了一长串的官方下载链接，老版本windows系统的IE浏览器渲染spice下载页面也存在问题。针对这种情况，可以先将<code>spice-guest-tools</code>文件下载到物理机局域网环境中的FTP中，然后基于中间FTP下载这个文件。等到虚拟机里面安装<code>spice-guest-tools</code>后，后续就可以直接通过鼠标拖动的方式将文件从物理机鼠标传输到虚拟机，不需要这么麻烦了。</p></blockquote><h2 id="四、配置文件共享" tabindex="-1">四、配置文件共享 <a class="header-anchor" href="#四、配置文件共享" aria-label="Permalink to &quot;四、配置文件共享&quot;">​</a></h2><p>文件共享可以通过<code>spice-webdavd</code>驱动实现。除此之外，前面的<code>spice-guest-tools</code>驱动本身也支持物理机到虚拟机的单向文件传输。</p><p>（1）配置物理机（宿主机）</p><ul><li>点击Boxes右上角【三个点】按钮</li><li>选择【首选项】</li><li>选中【设备及共享】标签页</li><li>点击【共享文件夹】组下的【+】按钮，自动弹出本地文件夹为【Public】的挂载配置（按需调整其它挂载路径）</li><li>点击【保存】</li></ul><p>（2）配置虚拟机（客户机）</p><ul><li>下载并安装<code>spice-webdavd</code></li><li>在【资源管理器】-【计算机】-【网络位置】中，查看挂载的【DavWWWRoot】驱动器</li></ul><blockquote><p>关于下载<code>spice-webdavd</code>的补充说明：前面已经安装<code>spice-guest-tools</code>了，可以直接通过鼠标拖动的方式将文件从物理机鼠标传输到虚拟机，也可以使用Boxes右上角【三个点】按钮的【发送文件...】功能</p></blockquote><h2 id="五、其它配置" tabindex="-1">五、其它配置 <a class="header-anchor" href="#五、其它配置" aria-label="Permalink to &quot;五、其它配置&quot;">​</a></h2><p>（1）修复Windows对文件共享50M大小限制的问题</p><p>在虚拟机中，基于文件共享获取物理机的<code>Firefox_Setup_115.37.0esr.exe</code>文件时报错：“文件大小超过允许的限制，无法保存”，此为Windows对于WebDAV文件大小的限制，可通过修改Windows注册表实现，步骤如下：</p><ul><li>点击键盘【Win + R】，输入【regedit】</li><li>找到【HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\services\\WebClient\\Parameter】项</li><li>在右边窗体区域右键点击【FileSizeLimitInBytes】，选择【修改】</li><li>在【数值数据】中填入【0xFFFFFF】</li><li>重启虚拟机</li></ul><p>（2）解决首次启动时虚拟机列表为空的问题</p><p>首次启动GnomeBoxes时，libvirt可能还未启动，导致虚拟机列表为空。可在开机时使用<code>virsh</code>命令自动激活<code>libvirt</code>会话，如下所示：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/autostart/libvirt-session-daemon.desktop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EOF</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">[Desktop Entry]</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Type=Application</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Name=Libvirt Session Daemon</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Comment=Start libvirt user session to trigger autostart VMs</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Exec=virsh -c qemu:///session uri</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">X-GNOME-Autostart-enabled=true</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span></code></pre></div>`,29)])])}const k=s(l,[["render",o]]);export{u as __pageData,k as default};
